// Phase 1 (milestone bulk-review-flow-ux / CON-swarm-intents-codegen) ·
// Phase 110-02 (D-08) per-swarm generalization. Codegen script: reads
// swarm_intents.intent_key from the live registry for ALL swarms and writes a
// generated TS per-swarm map + literal-union to
// web/lib/automations/debtor-email/coordinator/intent.generated.ts.
//
// Why: keeps strict TS compile-time safety AND zero-edit onboarding. After a
// new intent row is INSERTed into swarm_intents, run `npm run codegen` and
// commit the regenerated file. Operator never edits the .generated.ts by hand.
//
// Mirrors web/scripts/gen-tenant-domains.ts (the per-swarm-map model, D-08).
//
// Phase 110-02 (D-08): this script previously read a SINGLE swarm via the
// `process.env.SWARM_TYPE ?? "debtor-email"` hack + a per-call
// `.eq("swarm_type", …)` filter, and emitted a flat SWARM_INTENTS tuple. It now
// iterates ALL swarms (one query, group by swarm_type) and emits
// SWARM_INTENTS_BY_SWARM (a per-swarm map) plus a union-over-all-swarms `Intent`
// literal type. The map shape is safe even when a swarm has no intents yet
// (e.g. sales-email = []) because the union over all swarms stays non-empty
// (debtor still carries its intents) — the empty-union footgun (RQ4) is avoided.
//
// Run:   npx tsx scripts/gen-intent-types.ts
// CI:    npm run codegen
//
// Idempotent: if the on-disk content already matches, prints "already
// up-to-date" and exits 0 without rewriting (preserves mtime; clean diff).

import { createClient } from "@supabase/supabase-js";
import {
  writeFileSync,
  mkdirSync,
  readFileSync,
  existsSync,
} from "node:fs";
import { dirname, resolve } from "node:path";
import { config as loadDotenv } from "dotenv";

loadDotenv({ path: resolve(__dirname, "..", ".env.local") });

const OUTPUT_PATH = resolve(
  __dirname,
  "..",
  "lib",
  "automations",
  "debtor-email",
  "coordinator",
  "intent.generated.ts",
);

const HEADER = `// AUTO-GENERATED by scripts/gen-intent-types.ts (Phase 1 milestone bulk-review-flow-ux / CON-swarm-intents-codegen; Phase 110-02 / D-08 per-swarm map).
// DO NOT EDIT BY HAND. Run \`npm run codegen\` after registry changes.
//
// Source of truth: public.swarm_intents.intent_key (Phase 68 registry), grouped
// by swarm_type. Regenerate when a new intent is INSERTed into the registry.

`;

interface SwarmIntentKeyRow {
  swarm_type: string;
  intent_key: string;
}

function renderBody(rows: SwarmIntentKeyRow[]): string {
  if (rows.length === 0) {
    // Defensive: an empty registry shouldn't happen in practice, but emit a
    // valid TS file anyway so the build doesn't break in dev.
    return (
      `export const SWARM_INTENTS_BY_SWARM = {} as const;\n\n` +
      `export type Intent = never;\n`
    );
  }
  // Group intent_keys by swarm_type.
  const bySwarm = new Map<string, Set<string>>();
  for (const r of rows) {
    if (!bySwarm.has(r.swarm_type)) bySwarm.set(r.swarm_type, new Set());
    bySwarm.get(r.swarm_type)!.add(r.intent_key);
  }
  // Stable diff: sort swarm_type keys and the inner intent_key arrays
  // alphabetically.
  const sortedSwarms = [...bySwarm.keys()].sort((a, b) => a.localeCompare(b));
  const entries = sortedSwarms
    .map((swarmType) => {
      const keys = [...bySwarm.get(swarmType)!].sort();
      const list = keys.map((k) => `"${k}"`).join(", ");
      return `  ${JSON.stringify(swarmType)}: [${list}],`;
    })
    .join("\n");
  return (
    `export const SWARM_INTENTS_BY_SWARM = {\n${entries}\n} as const;\n\n` +
    `export type Intent =\n  (typeof SWARM_INTENTS_BY_SWARM)[keyof typeof SWARM_INTENTS_BY_SWARM][number];\n`
  );
}

export async function main(): Promise<void> {
  const url =
    process.env.SUPABASE_URL ?? process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key =
    process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SUPABASE_SERVICE_KEY;
  if (!url || !key) {
    throw new Error(
      "[gen-intent-types] SUPABASE_URL (or NEXT_PUBLIC_SUPABASE_URL) + SUPABASE_SERVICE_ROLE_KEY required",
    );
  }
  const admin = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // NOTE: public.swarm_intents has no `enabled` column (see migration
  // 20260504b_swarms_registry_generalisation.sql) — all rows are implicitly
  // enabled. No `.eq("enabled", true)` filter (matches the live schema).
  const { data, error } = await admin
    .from("swarm_intents")
    .select("swarm_type, intent_key")
    .order("swarm_type")
    .order("intent_key");
  if (error) {
    throw new Error(
      `[gen-intent-types] swarm_intents query failed: ${error.message}`,
    );
  }
  const rows: SwarmIntentKeyRow[] = (data ?? []).map(
    (r: { swarm_type: string; intent_key: string }) => ({
      swarm_type: r.swarm_type,
      intent_key: r.intent_key,
    }),
  );

  const next = HEADER + renderBody(rows);

  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  const existing = existsSync(OUTPUT_PATH)
    ? readFileSync(OUTPUT_PATH, "utf8")
    : null;

  if (existing === next) {
    console.log(
      `[gen-intent-types] already up-to-date (${rows.length} intent rows) — no write`,
    );
    return;
  }

  writeFileSync(OUTPUT_PATH, next, "utf8");
  console.log(
    `[gen-intent-types] wrote ${rows.length} intent rows to ${OUTPUT_PATH}`,
  );
}

// Auto-run when executed via `tsx scripts/gen-intent-types.ts` (mirrors
// gen-entity-types.ts). The `require.main === module` guard prevents
// accidental execution if this file is ever imported (Test 1 contract).
if (require.main === module) {
  main().catch((err) => {
    console.error("[gen-intent-types] FAILED:", err);
    process.exit(1);
  });
}
